def render(source):
    d=json.loads(source.read_text(encoding='utf-8-sig'));slides=d['slides']
    assert len(slides)>=10 and slides[-1]['layout']=='closing'
    assert slides[-1]['title']=='Дякую за увагу!' and not slides[-1].get('items')
    assert all(s.get('notes') for s in slides)
    articles='\n'.join(f'<article class="slide layout-{esc(s["layout"])}" aria-label="{i+1}. {esc(s["title"])}"{(" hidden" if i else "")}>{body(s,d)}<span class="slide-number" aria-hidden="true">{i+1:02}</span></article>' for i,s in enumerate(slides))
    embedded=json.dumps(d,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    page=f'''<!doctype html><html lang="uk"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(d['title'])}</title><link rel="icon" type="image/svg+xml" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='7' fill='%23172b46'/%3E%3Crect x='8' y='8' width='16' height='16' fill='%2362d7b5'/%3E%3C/svg%3E"><style>{CSS}\n{EXTRA_CSS}
.deck-blocks>div[data-category^="Basic"]{{background:#e8efff;border-color:#638cc4}}.deck-blocks>div[data-category^="Input"]{{background:#fae8f3;border-color:#c2669a}}.deck-blocks>div[data-category^="Radio"]{{background:#fae8f3;border-color:#c2669a}}.deck-blocks>div[data-category^="Variables"]{{background:#fbe8ec;border-color:#c16b83}}.deck-blocks>div[data-category^="Logic"]{{background:#e0f3f2;border-color:#4aa79d}}.deck-blocks>div[data-category^="Music"]{{background:#fde8e3;border-color:#be7861}}.deck-chain,.deck-loop{{width:100%;max-height:455px}}.chain-mobile,.loop-mobile{{display:none}}.chance-tokens{{display:grid;grid-template-columns:repeat(5,1fr);gap:22px;margin:20px 0 32px}}.chance-tokens span{{background:#e7ecea;border:2px solid #78988b;border-radius:18px;text-align:center;padding:15px;font-size:50px;font-weight:700}}.chance-tokens .token-0{{background:#c5f0dc;border-color:#13734f;color:#10583e}}.deck-blocks>div[data-category^="Math"]{{background:#eee3f7;border-color:#9b70bb}}.deck-blocks>div[data-category^="Loops"]{{background:#e1f4e8;border-color:#4e9972}}@media(max-width:600px){{.deck-chain,.deck-loop{{display:none}}.chain-mobile,.loop-mobile{{display:grid;gap:12px}}.chain-mobile>div,.loop-mobile li{{padding:14px;border:2px solid #b68b38;border-radius:12px;background:#fff5da;font-size:20px}}.chain-mobile small{{font-size:16px}}.chance-tokens{{gap:10px}}.chance-tokens span{{font-size:30px;padding:10px}}}}.fade-panels{{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;text-align:center}}.fade-panels figure{{margin:0;display:grid;justify-items:center;gap:18px}}.fade-panels figcaption{{font-size:32px;font-weight:700;color:#176b56}}.fade-panels svg{{width:180px;max-width:100%}}.deck-blocks>div[data-category*="Basic"]{{background:#e8efff;border-color:#638cc4}}.deck-blocks>div[data-category*="Input"]{{background:#fae8f3;border-color:#c2669a}}.deck-blocks>div[data-category*="Radio"]{{background:#fae8f3;border-color:#c2669a}}.deck-blocks>div[data-category*="Variables"]{{background:#fbe8ec;border-color:#c16b83}}.deck-blocks>div[data-category*="Logic"]{{background:#e0f3f2;border-color:#4aa79d}}.deck-blocks>div[data-category*="Math"]{{background:#eee3f7;border-color:#9b70bb}}.deck-blocks>div[data-category*="LED"]{{background:#eee3f7;border-color:#9b70bb}}@media(max-width:600px){{.fade-panels{{grid-template-columns:repeat(2,1fr);gap:24px 14px}}.fade-panels figcaption{{font-size:28px}}}}</style></head><body><div class="toolbar"><span class="deck-label">{esc(d['label'])}</span><span class="spacer"></span><div class="slide-picker-top"><span id="slidePickerNumber" aria-hidden="true">1</span><select id="slidePicker" aria-label="Перейти до слайда"></select></div><button id="notesToggle" aria-expanded="false" aria-controls="teacherNotes">Нотатки вчителя</button><button id="printDeck">Друк</button><button id="closeDeck" aria-label="Закрити презентацію й повернутися до уроку">Закрити ×</button></div><main aria-label="Слайди презентації">{articles}</main><nav class="navigation" aria-label="Навігація слайдами"><button id="prevSlide">← Назад</button><span id="slideCount" role="status" aria-live="polite"></span><button id="nextSlide">Далі →</button></nav><p class="key-hint">Клавіші ← → · Home / End · Esc — повернутися до уроку</p><aside id="teacherNotes" hidden><h2>Нотатки вчителя</h2><p id="notesText"></p><div id="notesSources"></div></aside><script id="presentationData" type="application/json">{embedded}</script><script>{JS}</script></body></html>'''
    source.with_name('presentation.html').write_text(page,encoding='utf-8')
    print(f'Rendered {len(slides)} slides')

if __name__=='__main__':render(Path(sys.argv[1]).resolve() if len(sys.argv)>1 else Path(__file__).with_name('presentation.json'))
